
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_revtm_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_revtm", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.762075260514531e-02, -3.722336486937265e-02, -3.664825423515761e-02, -3.581336472398790e-02, -3.459555233954764e-02, -3.280620865169001e-02, -3.015009380334709e-02, -2.617023686092421e-02, -2.032039095646485e-02, -1.312044191152088e-02, -1.043715671528626e-02, -3.823519229865895e-02, -4.548572843181432e-02, -2.813429559579864e-02, -1.360058591443400e-02, -3.539803158272813e-03, -2.234102327367713e-04, -1.683986590704218e-06, -7.007213138361564e-10, -9.035471208101119e-15]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


